    bounds = observation.get("bounds", None)  # expect tuple-like (minx, miny, maxx, maxy)
    def in_bounds(nx, ny):
        if bounds is None:
            return True
        try:
            minx, miny, maxx, maxy = bounds
            return minx <= nx <= maxx and miny <= ny <= maxy
        except Exception:
            return True

    # Simple reactive policy:
