    # If resources exist, choose move toward closest resource
    best = None
    best_dist = None
    if resources:
        for r in resources:
            if not isinstance(r, dict):
                continue
            rx = r.get("x", None)
            ry = r.get("y", None)
            if rx is None or ry is None:
